) AS (
  VALUES 
    (614::BIGINT, 'Pésima y detestable'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2026-07-23T00:00:00+00:00'::TIMESTAMPTZ, '0f6b0a0745a7fa37c301ce2417247a4b0a1bce09156653eb4d2bd89c75b35080'::TEXT, ARRAY[1880]::BIGINT[]),
    (614::BIGINT, 'Lo de favoritismo es real, pero si usted le habla con respeto y trata de convivir se vuelve alguien amable. Si usted va a aprender y es algo autodidacta va a ir bien. Las calificaciones se rigen a partir de como dibuja toda la clase (si todos dibujan excelente espérese un 70 en un buen dibujo)'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2026-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'd38777af620544f1260768f451efe5ed9355b2db21bfc0afa123a15ac162dc40'::TEXT, ARRAY[1847]::BIGINT[]),
    (614::BIGINT, 'Favoritismo, +60 tareas'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2025-10-19T00:00:00+00:00'::TIMESTAMPTZ, '1d0b490b98506450c9fdde6f89c5c378e03750d03eead9e341c8eb05ee59ec1d'::TEXT, ARRAY[1847]::BIGINT[]),
    (614::BIGINT, 'Es la única que da este curso asi que no hay de otra, de lo peor que hay en el tec, pide 64 trabajos a lo largo de todo el bloque y no revisa ni 1, pero si no lo entrega le baja la nota, si uno le reclama tiene las de perder, si la agarre contra ud, mamó.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2025-09-24T00:00:00+00:00'::TIMESTAMPTZ, '1702b87d33d7cfdd0b2581119cd27f56f27b8a7cf94835c0256f094ddb118b34'::TEXT, ARRAY[1847]::BIGINT[]),
    (614::BIGINT, 'La peor profe de diseño. En taller no enseña, ella ni siquiera da el ejemplo al dibujar. En principios es una mierda, usted tiene que aprender todo por su cuenta, en cultura más de lo mismo. Odiada por todos los profes de ahí, por algo nunca sale en las actividades de la escuela. Eso dice mucho.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'd327ed6d0b8f3082b4db97cace7eff49a365f20402442d124a317b573ea51708'::TEXT, ARRAY[1847, 1850, 1880]::BIGINT[]),
    (614::BIGINT, 'Mucho favoritismo, en realidad solo ayuda a los que sientan al frente, deja tareas confusas todos los días, además, la clase se basa en diapositivas con puros dibujos que nunca llega a explicar, igual no queda otra opción, si toca, toca'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas']::TEXT[], '2025-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'e7570f02768f287fd28db8fcfa60e0ca2ba00dc59238f2a51b733f72e7c40183'::TEXT, ARRAY[1847]::BIGINT[]),
    (614::BIGINT, 'Es la única profesora que da esta clase, entonces toca. Se contradice mucho explicando, tiene mucho favoritismo y generalmente solo le ayuda a quienes están al frente. Deja tareas largas cada lección y la retroalimentación a veces es confusa o no tiene nada que ver con lo que uno preguntó.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2025-05-01T00:00:00+00:00'::TIMESTAMPTZ, '3aad699689d714b9c71f51c287a4eddd284367e2db901fc1861d9059480c67af'::TEXT, ARRAY[1847]::BIGINT[]),
    (614::BIGINT, 'No enseña nada... asume que ya todos llegan sabiendo los principios de dibujo como axonometrias por ejemplo... basicamente... califica como si enseñara... no tiene sentido buscarla aquí porque es la unica que da taller de dibujo... resignese a sufrir... ciao'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2025-04-21T00:00:00+00:00'::TIMESTAMPTZ, '5ae6512eebf53cfd77b50e29680a8e037c05f6e8bb5de7f36a48449868bc4481'::TEXT, ARRAY[1847]::BIGINT[]),
    (614::BIGINT, 'Es cierto que hay mucha tarea pero este curso es regalado, la gente que se queja es vaga y no saben que los otros profes que habían antes eran mucho más duros. Silvia ayuda un montón y califica suave.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2025-02-10T00:00:00+00:00'::TIMESTAMPTZ, '27e81db85fc7f7215bfe26de2262a70032985750455d41531047aa69d546745f'::TEXT, ARRAY[1847]::BIGINT[]),
    (614::BIGINT, 'Realmente es una pésima profesora, pero no hay quite porque es la única, tiene mucho favoritismo, califica duro, deja una cantidad absurda de tareas, y su personalidad es irritante. Hace comentarios despectivos sobre sus alumnos y falta el respeto a los mismos, pero no hay más. Va a pasarla mal.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2024-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'e0b24e578a9d3e5d733e0fc16222ccd2fba50b3a1c2f072ffb51d3ca995a4c99'::TEXT, ARRAY[1847]::BIGINT[]),
    (614::BIGINT, 'La profe es buena nota pero su clase se vuelve demasiado tediosa y manda demasiada tarea. Sus retroalimentaciones no son nada claras y le encanta estar comparando el trabajo de los estudiantes, además de que no usa TecDigital así que uno no sabe cómo va. Y definitivamente tiene estudiantes favoritos'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Pocos exámenes']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '7ac10cb7639fef9a092cdae24c99f7087d5114b40ac2a4a205e87ea78c4b5bea'::TEXT, ARRAY[1847]::BIGINT[]),
    (614::BIGINT, 'Solo ayuda a los que se sientan al frente, si tenés una duda o hiciste algo mal te usara de ejemplo para la clase de lo que no hay que hacer, de manera humillante. Hice un total de 62 dibujos, de los cuales solo reviso 4 o 5, por ende no se sabe que hago bien o mal. No usa Tec Digital.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-23T00:00:00+00:00'::TIMESTAMPTZ, '329e5f523c69a5bba91af8d31524ee767660634e0fc747624bfea1484b20356f'::TEXT, ARRAY[1847]::BIGINT[]),
    (614::BIGINT, 'En sí el curso es muy pesado porque son muchas tareas, pero la profe explica muy bien, es paciente a la hora de explicar y muy buena gente también.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2024-02-02T00:00:00+00:00'::TIMESTAMPTZ, '3f4ce1eacd323a2f25c6946e32a29b605cd3d8a6045a74bcb8df77743fce73a1'::TEXT, ARRAY[1847]::BIGINT[]),
    (614::BIGINT, 'Es muy buena profe y califica muy suave la verdad. En general el curso es muy tedioso por que son demasiados trabajos pero con que uno hagas las tareas y que tenga más de 55 en los examenes se pasa el curso. Además trata a los estudiantes super bien y las clases son muy entretenidas.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-17T00:00:00+00:00'::TIMESTAMPTZ, '35b7973e54cb816a360da4faecd58876a67c421d3d6521095006430c27deb7db'::TEXT, ARRAY[1847]::BIGINT[]),
    (614::BIGINT, 'El curso en si es muy demandante, pero la profe lo hace muy llevadero. Es muy compresiva y hace las clases muy amenas, solo que si deja muchas tareas las cuales toman bastante tiempo. No tenga miedo de matricular con ella, al menos en este curso es muy buena y se aprende mucho.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2023-07-06T00:00:00+00:00'::TIMESTAMPTZ, '46eabcc1bb1aea84c7115563658e825d61949f799df3d6611b57ccd6223b2389'::TEXT, ARRAY[1847]::BIGINT[]),
    (614::BIGINT, 'La profe es muy amable y agradable, en general explica bastante bien, solo que a veces no da mucha retroalimentación. El curso en sí no es difícil, solo que si puede llegar a quitar mucho tiempo, pero la profe entiende y está dispuesta a ayudar'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, '7be80c6f586c64a59683613a9c5c8604597514172216700d2fc1f71e2af66c21'::TEXT, ARRAY[1847]::BIGINT[]),
    (614::BIGINT, 'Para taller de dibujo es muy buena, incluso mejor que Vicky, es muy amable, siempre está dispuesta a ayudar y hacer que el curso no sea pesado, trabaja mucho con los dibujos y objetos de Vicky pero explica a su manera y sus técnicas son excelentes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Respetado por los estudiantes']::TEXT[], '2022-12-30T00:00:00+00:00'::TIMESTAMPTZ, 'd9f7ef4302467b077340cf1343868151f8853f853871b0a9a02a40c0027cc1e3'::TEXT, ARRAY[1847]::BIGINT[]),
    (614::BIGINT, 'Los trabajos son bastante pesados. Ayuda a los estudiantes, pero son ellos los que dan la clase. Le falta un poco de organización, pero el curso es llevadero.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Muchos proyectos grupales']::TEXT[], '2021-06-30T00:00:00+00:00'::TIMESTAMPTZ, '8bee7dbaeb8ad6b4bfc8d254d104c0ab2b679240c5f1d25a1fc42e06cf15c90a'::TEXT, ARRAY[1880]::BIGINT[]),
    (614::BIGINT, 'Es un amor de persona, pero los estudiantes dan la clase, los trabajos son tediosos y las instrucciones son muy confusas! El curso virtual era sólo entregar trabajos, ojalá se pueda adaptar mejor'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, '473f9154d8a7742b39287bb45010ca911088fde10a8522108ad137ae5a0ef3f5'::TEXT, ARRAY[1880]::BIGINT[]),
    (614::BIGINT, 'La profesora en sí es muy buena persona, aunque las rúbricas y cronogramas no son tan fáciles de entender o constantemente se alteran.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Muchos proyectos grupales']::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, 'd282cf2417abb740d0e6e090533450c636deca2645c7421536626ce164df349b'::TEXT, ARRAY[1880]::BIGINT[]),
    (614::BIGINT, 'El curso es fácil, pero con esta profe da tristeza y no dan ganas de llevarlo. Deja muchísimos trabajos que a pesar de no ser difíciles, son muy largos y demasiado mediocres. Su cronograma da asco y todas las presentaciones las hace uno, prácticamente los estudiantes dan toda la clase por ella.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '5bd9db01db83fe119e438f1ce87b6b622f1aec3a88c7b1f1cb6ce1434622da71'::TEXT, ARRAY[1880]::BIGINT[]),
    (614::BIGINT, 'Es demasiado buena profe y persona. Su único pecado es que hace las presentaciones un toque largas y entonces uno se aburre. Pero por lo demás, es excelente. Llevaría todos los cursos que pueda con ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-27T00:00:00+00:00'::TIMESTAMPTZ, 'ab1907d581e33cb9a3408d193313f1a414354edecd06acb0455bb11827921f95'::TEXT, ARRAY[1848, 1880]::BIGINT[]),
    (614::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2019-01-24T00:00:00+00:00'::TIMESTAMPTZ, 'e35bb899f924229134710e4b9e7a8396692652af7e61e4222192c9922974c7c5'::TEXT, ARRAY[1880]::BIGINT[]),
    (614::BIGINT, 'La profesora es muy buena gente y noto que ahora está intentando también ser mejor profesora. Es muy flexible e intenta ayudar a los estudiantes que estén interesados en la materia.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2019-01-17T00:00:00+00:00'::TIMESTAMPTZ, '50ae1b2fcf15563d547b7e2e7650033d6824db47e59026e38cfc3a8c4911a789'::TEXT, ARRAY[1880]::BIGINT[]),
    (614::BIGINT, 'Los métodos de evaluación de esta profesora son ineficientes. Ayuda mucho, pero califica muy extraño. Algunas veces a trabajos mediocres les coloca el famoso sello (se va a dar cuenta de lo que es cuando entre) y a otros mejores no. Al final se va a dar cuenta que va a llegar mamando a repre II.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2016-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'd25c23b0e786e437d9592b43bd5496dd79eff178e90ac40ae6b28c3df806898e'::TEXT, ARRAY[1927, 1179]::BIGINT[]),
    (614::BIGINT, 'No es tan mala como todos dicen, es muy fácil y califica suave'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-02-01T00:00:00+00:00'::TIMESTAMPTZ, '6d9c37f08d723a8a48d5ce6915c2f17a444f21370d534bb9f4e8959dc9e13a73'::TEXT, ARRAY[1859, 1860, 1927]::BIGINT[]),
    (614::BIGINT, 'NUNCA USE AMARILLO! Es muy subjetiva, cambia de criterio cada 5 minutos, no sabe mucho y es aburrida, aunque es muy exigente. Se aprende poco en sus cursos. Y SIEMPRE tiene argolla con algún estudiante, hasta se hacen amigos y todo. Ahhh y es la copia baratísima de Vicky...'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('15','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-16T00:00:00+00:00'::TIMESTAMPTZ, '2e3117e263d68f3365102f8c2d77c90a55134d5b3a4fbbd7a1672e96fff62f52'::TEXT, ARRAY[1925, 1929, 1927]::BIGINT[]),
    (614::BIGINT, 'En Teo súper fácil y Repre si ve que vas mejorando te ayuda. Esta profe sí tiene preferencias, use turquesas, cafés y búhos. para ganársela muestren interés y vayan a consulta -a esta profe ni idea de porqué le meten miedo al principio-'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-12T00:00:00+00:00'::TIMESTAMPTZ, '7573e0a7cff5a01332abcc2fedd557b720b9b6a9b283ed9aafe4b54dc835b6d4'::TEXT, ARRAY[1848, 1927]::BIGINT[]),
    (614::BIGINT, 'Es buena profe, eso si no usen amarillo en los trabajos, en repre califica un poco duro pero nada fuera de lo normal'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-07-03T00:00:00+00:00'::TIMESTAMPTZ, '2546724c1949dc080484df7d07ec4904c70c38d95c5de518942444b114ed4587'::TEXT, ARRAY[1925, 1929, 1927]::BIGINT[]),
    (614::BIGINT, 'Use colores cafés y turquesas, ni siquiera piense en decirle algo de mariposas le da un paro si se las menciona, favoritismo, usted va a consulta le dice que todo esta bien y luego no todo esta mal y le pone una baja nota, lo rescatable es que es de las pocas que califica con rúbrica en el diseño'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-07-03T00:00:00+00:00'::TIMESTAMPTZ, '5fd603eb0dec38c4d11897347d32d9dabb251b70a615bbbee8af4f39c62b5601'::TEXT, ARRAY[1925, 1927]::BIGINT[]),
    (614::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-28T00:00:00+00:00'::TIMESTAMPTZ, 'cfb8b0806fa7abab76aed6b6f513fd7f1877fc163a52262a5a12315d914a885e'::TEXT, ARRAY[1925]::BIGINT[]),
    (614::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'fd3564a19fa7ec3d624f6d08646a5be6c08e402efdca4c59e38ca35387ca963f'::TEXT, ARRAY[1859, 1860]::BIGINT[])
